            t = dx;
            dx = -dy;
            dy = t;
        }
        x += dx;
        y += dy;
    }

    return sequence;
}

int main() {
    int w = 4; // Example width
    int h = 3; // Example height

    std::vector<std::pair<int, int>> sequence = generateSequence(w, h);

    for (const auto& coord : sequence) {
        std::cout << "(" << coord.first << ", " << coord.second << "), ";
    }

    return 0;
}
